      const slides=[...carousel.children],article=carousel.closest('.chat-inline-media'),indexNode=article?.querySelector('[data-carousel-index]'),previous=article?.querySelector('[data-carousel-move="-1"]'),next=article?.querySelector('[data-carousel-move="1"]');let frame=0,startX=0,startScroll=0,suppressUntil=0;
