      attachment.items=ids.map(id=>{const matches=files.filter(file=>String(file.item_id)===id);return{id,final:matches.find(file=>file.role==='final'||file.role==='image')||null,stage1:matches.find(file=>file.role==='stage1')||null,details:matches.filter(file=>file.role==='detail'),upscales:matches.filter(file=>file.role==='upscale')}})
